import test from 'node:test';
import assert from 'node:assert/strict';
import {initial,legalActions,canApply,applyAction} from './rules.mjs';
const play=(s,a)=>{const r=applyAction(s,a);assert.equal(r.error,undefined);return r.position;};

test('ordinary win terminates before AI reply',()=>{
 const s=initial(['X','X',null,'O','O',null,null,null,null]);
 const n=play(s,{type:'Place',at:2});
 assert.equal(n.result,'X');assert.deepEqual(legalActions(n),[]);
});
test('Shatter cannot convert; rejection is nonthrowing and pure',()=>{
 const s=initial(['O',null,null,null,null,null,null,null,null],'X',{shatter:1});
 const before=JSON.stringify(s),a={type:'Shatter',remove:0,at:0};
 assert.equal(canApply(s,a),false);assert.deepEqual(applyAction(s,a),{error:'ILLEGAL_ACTION'});
 assert.equal(JSON.stringify(s),before);
 const n=play(s,{type:'Shatter',remove:0,at:1});
 assert.equal(n.cells[0],null);assert.equal(n.cells[1],'X');assert.equal(n.powersX.shatter,0);
});
test('incomplete and malformed preview actions reject safely',()=>{
 const s=initial();
 for(const a of [null,undefined,{}, {type:'Place'}, {type:'Place',at:99}, {type:'Place',at:'0'}]){
  assert.equal(canApply(s,a),false);assert.equal(applyAction(s,a).error,'ILLEGAL_ACTION');
 }
});
test('Shatter clears rock',()=>{
 const s=initial(['rock',null,null,null,null,null,null,null,null],'X',{shatter:1});
 assert.equal(play(s,{type:'Shatter',remove:0,at:4}).cells[0],null);
});
test('Slide permits vacated origin',()=>{
 const s=initial(['X',null,null,null,null,null,null,null,null],'X',{slide:1});
 const n=play(s,{type:'Slide',from:0,to:4,at:0});
 assert.equal(n.cells[0],'X');assert.equal(n.cells[4],'X');assert.equal(n.powersX.slide,0);
});
test('AI Ward blocks Slide destinations, then expires',()=>{
 const s=initial(['X',null,null,null,null,null,null,null,null],'O',{slide:1},1);
 const ward=play(s,{type:'Ward',at:8,shieldCell:4});
 assert.equal(ward.shield.blockedActor,'X');assert.equal(ward.wardO,0);
 assert(!legalActions(ward).some(a=>a.at===4||a.to===4));
 const n=play(ward,{type:'Slide',from:0,to:1,at:0});
 assert.equal(n.shield,null);assert.equal(n.toMove,'O');
});
test('shield blocks Shatter placement, not its unshielded alternative',()=>{
 const s=initial(['O',null,null,null,null,null,null,null,null],'X',{shatter:1});
 s.shield={cell:4,blockedActor:'X'};
 assert.equal(canApply(s,{type:'Shatter',remove:0,at:4}),false);
 assert.equal(applyAction(s,{type:'Shatter',remove:0,at:4}).error,'ILLEGAL_ACTION');
 assert(!legalActions(s).some(a=>a.type==='Shatter'&&a.at===4));
 const n=play(s,{type:'Shatter',remove:0,at:1});
 assert.equal(n.shield,null);assert.equal(n.powersX.shatter,0);
});
test('new Ward survives old Ward expiration',()=>{
 const s=initial(['X',null,null,null,null,null,null,null,'O'],'X',{ward:1});
 s.shield={cell:4,blockedActor:'X'};
 assert.deepEqual(play(s,{type:'Ward',at:1,shieldCell:2}).shield,{cell:2,blockedActor:'O'});
});
test('Ward cannot remove last reply when neither placement wins',()=>{
 const s=initial(['X','O','X','X','O','O','O',null,null],'X',{ward:1});
 assert(!legalActions(s).some(a=>a.type==='Ward'));
 assert.equal(canApply(s,{type:'Place',at:7}),true);
 assert.equal(canApply(s,{type:'Place',at:8}),true);
});
test('winning Ward needs no shieldCell',()=>{
 const s=initial(['X','X',null,'O','O',null,null,null,null],'X',{ward:1});
 assert.equal(canApply(s,{type:'Ward',at:2}),true);
 const n=play(s,{type:'Ward',at:2});
 assert.equal(n.result,'X');assert.equal(n.shield,null);assert.equal(n.powersX.ward,0);
});
test('extra Ward copies do not duplicate action branches',()=>{
 const one=initial(Array(9).fill(null),'X',{ward:1});
 for(const count of [2,3]){
  const many={...one,powersX:{...one.powersX,ward:count}};
  const actions=legalActions(many);
  assert.deepEqual(actions,legalActions(one));
  assert.equal(new Set(actions.map(a=>JSON.stringify(a))).size,actions.length);
  assert.equal(play(many,{type:'Ward',at:0,shieldCell:1}).powersX.ward,count-1);
 }
});
test('rock-filled board draws despite held power',()=>{
 const s=initial(['X','O','X','X','O','O','O',null,'rock'],'X',{shatter:1});
 assert.equal(play(s,{type:'Place',at:7}).result,'draw');
});
test('enumerated actions apply without input mutation',()=>{
 const s=initial(['X',null,null,null,'O',null,null,null,null],'X',{slide:1,ward:1,shatter:1});
 const before=JSON.stringify(s);
 for(const a of legalActions(s)){
  assert.equal(canApply(s,a),true);
  const n=play(s,a);assert.equal(JSON.stringify(s),before);
  assert(n.powersX.slide>=0&&n.powersX.ward>=0&&n.powersX.shatter>=0);
 }
});

Copy beside rules.mjs and ai.worker.mjs. Not executed. v4 adds a controller-owned 1.2s watchdog and event-based Heat. cancelAI is cleanup only; revision/inFlight guards guarantee stale replies cannot commit. Keep the v3 UI patch. Heat: +1 per placement, +2 per power (either actor), +3 for an X line, capped at 10; reset on every fresh board.

import {initial,canApply,applyAction} from './rules.mjs';
import {tacticalFallback} from './ai.worker.mjs';
const TYPES=['shatter','slide','ward'];
export function createController({render,requestAI,cancelAI=()=>{},onOutcome=()=>{},later=setTimeout,reducedMotion=false,now=()=>performance.now()}){
 let revision=0,inFlight=null,s;
 const snapshot=()=>structuredClone(s),publish=()=>render(snapshot());
 const locked=()=>now()<s.inputLockedUntil;
 function cancelWork(){try{cancelAI();}catch{/* Cleanup failure must not freeze play. */}}
 function stopAI(){const active=inFlight!==null;inFlight=null;if(active)cancelWork();}
 function wait(ms,fn){const r=revision,phase=s.phase;later(()=>{if(r===revision&&s.phase===phase)fn();},ms);}
 function guard(){s.inputLockedUntil=now()+250;wait(250,publish);}
 function end(phase){s.phase=phase;publish();onOutcome(snapshot());}
 function newRun(){
  stopAI();revision++;
  s={revision,phase:'draft',level:1,drawsThisLevel:0,boardsLeft:3,secondWindAvailable:true,heat:0,score:0,powersSpentThisLevel:0,
   inventory:{shatter:0,slide:0,ward:0},position:null,events:[],starterDraft:true,lossReason:null,inputLockedUntil:0};publish();
 }
 function freshBoard(){
  stopAI();revision++;s.revision=revision;
  const cells=Array(9).fill(null);
  if(s.level===2)cells[0]='rock';if(s.level===3){cells[0]='X';cells[8]='O';}
  s.position=initial(cells,s.level===4?'O':'X',s.inventory,s.level===5?1:0);
  s.heat=0;s.events=[];s.lossReason=null;s.inputLockedUntil=0;
  s.phase=s.position.toMove==='X'?'player':'ai';publish();kickAI();
 }
 function draft(type,replace=null){
  if(s.phase!=='draft'||locked())return false;
  const total=Object.values(s.inventory).reduce((a,b)=>a+b,0);
  if(type===null){if(s.starterDraft||(s.level===5&&total===0))return false;}
  else {
   if(!TYPES.includes(type))return false;
   if(total>=3){if(!TYPES.includes(replace)||s.inventory[replace]<1)return false;s.inventory[replace]--;}
   s.inventory[type]++;
  }
  s.starterDraft=false;freshBoard();return true;
 }
 function lose(reason){
  s.phase='lost';s.lossReason=reason;publish();
  wait(reducedMotion?0:1000,()=>{
   if(s.secondWindAvailable){
    s.secondWindAvailable=false;
    if(reason==='boards')s.boardsLeft=1;
    freshBoard();
   }else end('defeat');
  });
 }
 function settle(){
  const result=s.position.result;
  if(result==='X'){
   if(s.level===5){end('victory');return;}
   const from=s.boardsLeft;
   s.level++;s.drawsThisLevel=0;s.boardsLeft=3;s.powersSpentThisLevel=0;
   s.phase='draft';s.events=[{type:'heartsRefill',from,to:3}];guard();publish();return;
  }
  if(result==='draw'){
   s.drawsThisLevel++;s.boardsLeft--;
   if(s.boardsLeft===0){lose('boards');return;}
   freshBoard();return;
  }
  s.phase=s.position.toMove==='X'?'player':'ai';publish();kickAI();
 }
 function skipWon(){if(s.phase!=='won'||locked())return false;settle();return true;}
 function commit(action,actor='X'){
  if((actor==='X'&&(s.phase!=='player'||locked()))||(actor==='O'&&s.phase!=='ai'))return false;
  if(s.position.toMove!==actor)return false;
  const r=applyAction(s.position,action);if(r.error)return false;
  revision++;s.revision=revision;s.position=r.position;s.inventory={...r.position.powersX};s.events=r.events;
  const spent=r.events.filter(e=>e.type==='power'&&e.actor==='X').length;
  s.powersSpentThisLevel+=spent;s.score+=25*spent;
  const placements=r.events.filter(e=>e.type==='placement').length;
  const powers=r.events.filter(e=>e.type==='power').length;
  s.heat=Math.min(10,s.heat+placements+2*powers+(r.position.result==='X'?3:0));
  if(r.position.result==='O')lose('line');
  else if(r.position.result==='X'){
   s.score+=100+50*s.boardsLeft;s.phase='won';guard();publish();wait(reducedMotion?250:700,settle);
  }else{s.phase='transition';publish();wait(reducedMotion?0:300,settle);}
  return true;
 }
 function kickAI(){
  if(s.phase!=='ai'||inFlight!==null)return;
  const r=revision;inFlight=r;
  const current=()=>inFlight===r&&revision===r&&s.phase==='ai';
  const payload={revision:r,position:structuredClone(s.position),level:s.level,drawsThisLevel:s.drawsThisLevel};
  function receive(reply){
   if(!current())return;
   inFlight=null;
   const a=reply?.revision===r&&canApply(s.position,reply.action)?reply.action:tacticalFallback(s.position);
   if(a)commit(a,'O');
  }
  later(()=>{
   if(!current())return;
   // Invalidate BEFORE cleanup: cancelAI need not settle its promise.
   revision++;s.revision=revision;inFlight=null;cancelWork();
   const a=tacticalFallback(s.position);
   if(a&&canApply(s.position,a))commit(a,'O');
  },1200);
  try{Promise.resolve(requestAI(payload)).then(receive,()=>receive(null));}catch{receive(null);}
 }
 function preview(action){return s.phase==='player'&&!locked()?applyAction(s.position,action):{error:'INPUT_LOCKED'};}
 newRun();
 return {newRun,draft,preview,skipWon,commit:action=>commit(action,'X'),getState:snapshot};
}

HUD only; board renderer and scene art remain separate. Uses the approved reference's hierarchy, not the picture as a baked-in clickable board. Copy JS into hud.mjs; CSS into stylesheet. No assets generated. Not executed.

export function createHUD(root,{onDraft,onAgain,onPower}){
 let last=null,selected=null,replace=null,draftKey='';
 const powers=[['shatter','✂','Shatter'],['slide','↷','Slide'],['ward','☕','Ward']];
 function render(s){
  last=s;
  const nextKey=s.phase==='draft'?`${s.level}:${s.starterDraft}`:'';
  if(nextKey!==draftKey){selected=null;replace=null;draftKey=nextKey;}
  const left=3-s.drawsThisLevel;
  const inv=s.inventory,total=Object.values(inv).reduce((a,b)=>a+b,0);
  const phaseText={draft:'Choose a sewing tool',player:'Your stitch',ai:'Granny Owl is thinking',lost:'The quilt unravels…',transition:'Threading…',victory:'A quilt well made!',defeat:'Shall we stitch again?'}[s.phase];
  const shield=s.position?.shield;
  root.innerHTML=`
   <header class="cottage-hud">
    <ol class="houses" aria-label="Level ${s.level} of 5">${[1,2,3,4,5].map(n=>`<li class="house ${n===s.level?'current':''}" ${n===s.level?'aria-current="step"':''}>${n}</li>`).join('')}</ol>
    <div class="attempts" aria-label="${left} board attempts left"><span aria-hidden="true">${'♥'.repeat(left)}${'♡'.repeat(3-left)}</span><small>Boards left: ${left}/3</small></div>
   </header>
   <p class="turn-status" role="status">${phaseText}</p>
   <aside class="hearth"><label for="hearth-gauge">HEARTH</label><meter id="hearth-gauge" min="0" max="10" value="${s.heat}">${s.heat}/10</meter><span>${s.heat}/10</span></aside>
   <p class="ward-status">${shield?`Teacup: blocked for ${shield.blockedActor==='X'?'your':'Owl’s'} next move; lifts after that action.`:'No cell shielded.'}</p>
   <small>Second Wind: ${s.secondWindAvailable?'ready':'used'} · Owl Ward: ${s.level===5?(s.position?.wardO?'ready':'used'):'—'}</small>
   <nav class="sewing-tray" aria-label="Power tools">${powers.map(([id,icon,name])=>`<button data-power="${id}" ${s.phase!=='player'||!inv[id]?'disabled':''}><span aria-hidden="true">${icon}</span>${name} ×${inv[id]}</button>`).join('')}</nav>
   ${s.phase==='draft'?`<section class="draft" aria-label="Choose a power">
    <div>${powers.map(([id,icon,name])=>`<button data-pick="${id}" aria-pressed="${selected===id}">${icon} ${name}</button>`).join('')}</div>
    ${total>=3?`<p>Tray full: choose a tool to replace.</p>${powers.filter(([id])=>inv[id]).map(([id,,name])=>`<button data-replace="${id}" aria-pressed="${replace===id}">${name} ×${inv[id]}</button>`).join('')}`:''}
    <button data-confirm ${!selected||(total>=3&&!replace)?'disabled':''}>Keep tool</button>
    ${s.starterDraft?'':'<button data-skip>Skip</button>'}</section>`:''}
   ${['victory','defeat'].includes(s.phase)?'<button data-again>Again</button>':''}`;
  root.querySelectorAll('[data-power]').forEach(b=>b.onclick=()=>onPower(b.dataset.power));
  root.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{selected=b.dataset.pick;render(last);});
  root.querySelectorAll('[data-replace]').forEach(b=>b.onclick=()=>{replace=b.dataset.replace;render(last);});
  const confirm=root.querySelector('[data-confirm]');if(confirm)confirm.onclick=()=>onDraft(selected,replace);
  const skip=root.querySelector('[data-skip]');if(skip)skip.onclick=()=>onDraft(null);
  const again=root.querySelector('[data-again]');if(again)again.onclick=onAgain;
 }
 return render;
}

